/**
 * OSW-PE-SNL-PYR-01 Rev. 02: machine-wise and part-wise pyro-line sensor register with design and
 * operating ranges — 294 register positions in 9 machine groups: 258 online
 * (one with a calculated companion value, ONLINE¹), 24 cyclone positions whose tags are on hold
 * (doc HP-02; placeholders riser duct pressure / temperature = PRS-PHC-0n / TMP-PHC-0n, cone pressure /
 * temperature = PRS-PHC-1n / TMP-PHC-2n), 4 conditional (fitted only if available),
 * 6 calculated (ΔP = inlet − outlet, bin weight = sum of the load cells) and 2 manual records.
 * Rev. 02 removes 27 Rev. 01 points (CAL-BRN-01, CAL-KLN-03, CAL-KLN-06, CAL-PHC-01, ELE-BGH-02, ELE-KFS-02, LEV-KLN-02, LEV-KLN-03, LEV-KLN-04, LEV-KLN-05, LEV-KLN-06, LEV-KLN-07, PRS-CLR-07, PRS-PHC-07, PRS-PHC-08, PRS-PHC-09, STS-CLR-01, STS-FSL-02, STS-KFS-01, TMP-CLR-07, TMP-CLR-11, TMP-CLR-12, TMP-CLR-13, TMP-CLR-14, TMP-CLR-15, TMP-CLR-16, TMP-KLN-21).
 * The register of record for which points exist, their short name, what they measure, signal type,
 * mounting location, status, source and the sub-assembly / detail sheet they belong to. Generated from
 * the PDF register (rev02/spec.json); edit the extraction, not by hand.
 */

export interface PyroSensorListEntry {
  tag: string;
  /** Short name ("Silo level (radar, roof)"). */
  name: string;
  /** What it measures, as printed in the register. */
  what: string;
  /** Register unit ("% FLA", "mbar", "status"). */
  unit: string;
  /** Sensor / signal type. */
  type: string;
  location: string;
  status: "REQUIRED" | "OPTIONAL" | "MANUAL";
  /** Existing DCS (verify) · New sensor · Verify / new · Calculated · Manual record. */
  source: string;
  /** Register class: online, online with a calculated companion (¹), calculated, manual, conditional (fitted if available) or tag on hold. */
  class: "ONLINE" | "ONLINE¹" | "CALC" | "MANUAL" | "COND" | "TAG HOLD";
  /** The tag is a placeholder on hold (doc HP-02): show "tag on hold" where the register is shown in detail. */
  tagHold?: boolean;
  /** Tag as printed when it differs from the code tag (the cyclone placeholders). */
  docTag?: string;
  /** Machine group code ("FSL-01"). */
  group: string;
  /** Part (table) title. */
  part: string;
  /** Detail sheet of the part ("F-1"). */
  sheet: string;
  /** Sub-assembly id ("fsl-silo"). */
  sub: string;
}

